Para resolver este problema, podemos analisar o comportamento das retas nos extremos do intervalo $[X_1, X_2]$.

Para cada reta $i$, definimos os valores de $y$ nos limites $X_1$ e $X_2$:
- $y_{i, 1} = A_i \cdot X_1 + B_i$
- $y_{i, 2} = A_i \cdot X_2 + B_i$

Duas retas distintas $i$ e $j$ **não** se intersectam dentro do intervalo $[X_1, X_2]$ se, e somente se, uma estiver estritamente acima da outra durante todo o intervalo, o que equivale a:
$$(y_{i, 1} < y_{j, 1} \text{ e } y_{i, 2} < y_{j, 2}) \quad\text{ou}\quad (y_{i, 1} > y_{j, 1} \text{ e } y_{i, 2} > y_{j, 2})$$

Em qualquer outro caso (se as ordens relativas se invertem ou se coincidem em $X_1$ ou $X_2$), as duas retas se cruzam em algum ponto com coordenada $x \in [X_1, X_2]$.

Portanto, o número total de pares de retas que se intersectam no intervalo é:
$$\binom{N}{2} - (\text{número de pares sem interseção})$$

Contar os pares com $y_{i, 1} < y_{j, 1}$ e $y_{i, 2} < y_{j, 2}$ é um problema clássico de contagem de inversões / dominância 2D, que pode ser resolvido eficientemente em $O(N \log N)$ utilizando ordenação e uma Fenwick Tree (Binary Indexed Tree) com compressão de coordenadas.

### Código em C++

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

typedef __int128_t int128;

struct Line {
    long long y1;
    long long y2;
};

struct FenwickTree {
    int n;
    vector<int> tree;
    FenwickTree(int n) : n(n), tree(n + 1, 0) {}

    void add(int i, int delta) {
        for (; i <= n; i += i & -i) {
            tree[i] += delta;
        }
    }

    int query(int i) {
        int sum = 0;
        for (; i > 0; i -= i & -i) {
            sum += tree[i];
        }
        return sum;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    long long X1, X2;
    if (!(cin >> n >> X1 >> X2)) return 0;

    vector<Line> lines(n);
    vector<long long> all_y2;
    all_y2.reserve(n);

    for (int i = 0; i < n; ++i) {
        long long a, b;
        cin >> a >> b;
        lines[i].y1 = a * X1 + b;
        lines[i].y2 = a * X2 + b;
        all_y2.push_back(lines[i].y2);
    }

    // Compressão de coordenadas para os valores de y2
    sort(all_y2.begin(), all_y2.end());
    all_y2.erase(unique(all_y2.begin(), all_y2.end()), all_y2.end());

    // Ordenar as retas por y1 crescente.
    // Em caso de empate de y1, ordenar por y2 decrescente para que
    // pontos com mesmo y1 não sejam contados como estritamente menores.
    sort(lines.begin(), lines.end(), [](const Line& a, const Line& b) {
        if (a.y1 != b.y1) {
            return a.y1 < b.y1;
        }
        return a.y2 > b.y2;
    });

    FenwickTree bit(all_y2.size());
    long long no_intersection_pairs = 0;

    for (int i = 0; i < n; ++i) {
        // Encontrar a posição comprimida de y2 (1-indexada)
        int rank = lower_bound(all_y2.begin(), all_y2.end(), lines[i].y2) - all_y2.begin() + 1;

        // Contar quantos elementos já inseridos possuem y2 estritamente menor (rank - 1)
        no_intersection_pairs += bit.query(rank - 1);

        // Inserir o elemento atual
        bit.add(rank, 1);
    }

    long long total_pairs = (long long)n * (n - 1) / 2;
    long long ans = total_pairs - no_intersection_pairs;

    cout << ans << "\n";

    return 0;
}
```

